using System.Data.Common;
using Careflow.Application;
using Careflow.Domain;
namespace Careflow.Infrastructure;

public sealed partial class SqlHospitalStore
{
    private const string RadiologyOrderColumns = "Id,Number,PatientId,EncounterId,AdmissionId,ProcedureName,Modality,BodyPart,Laterality,Priority,Status,Accession,ClinicalNote,OrderedBy,OrderedAtUtc,ScheduledAtUtc,PerformedAtUtc,StudyUid,Version";
    private static RadiologyOrder MapRadiologyOrder(DbDataReader r) => new(G(r, "Id"), S(r, "Number"), G(r, "PatientId"), GN(r, "EncounterId"), GN(r, "AdmissionId"), S(r, "ProcedureName"), S(r, "Modality"), S(r, "BodyPart"), S(r, "Laterality"), S(r, "Priority"), S(r, "Status"),
        S(r, "Accession") is "" ? null : S(r, "Accession"), S(r, "ClinicalNote"), G(r, "OrderedBy"), T(r, "OrderedAtUtc"), TN(r, "ScheduledAtUtc"), TN(r, "PerformedAtUtc"), S(r, "StudyUid") is "" ? null : S(r, "StudyUid"), L(r, "Version"));
    private const string RadiologyReportColumns = "Id,OrderId,Version,Findings,Impression,Critical,Status,ReportedBy,ReportedAtUtc,AuthorizedBy,AuthorizedAtUtc,ContentHash";
    private static RadiologyReport MapRadiologyReport(DbDataReader r) => new(G(r, "Id"), G(r, "OrderId"), I(r, "Version"), S(r, "Findings"), S(r, "Impression"), B(r, "Critical"), S(r, "Status"), G(r, "ReportedBy"), T(r, "ReportedAtUtc"), GN(r, "AuthorizedBy"), TN(r, "AuthorizedAtUtc"), S(r, "ContentHash") is "" ? null : S(r, "ContentHash"));
    private static EmergencyRegistration MapEmergencyRegistration(DbDataReader r) => new EmergencyRegistration(G(r, "Id"), S(r, "Number"), GN(r, "PatientId"), S(r, "PatientName"), S(r, "Sex"), r["DateOfBirth"] is DBNull ? null : Date(r, "DateOfBirth"), S(r, "ArrivalMode"), S(r, "Status"), T(r, "ArrivedAtUtc"), G(r, "CreatedBy"), L(r, "Version")) with { ReferringFacility = S(r, "ReferringFacility"), BroughtBy = S(r, "BroughtBy"), MedicoLegalCase = B(r, "MedicoLegalCase") };
    private static VitalSet MapVitals(DbDataReader r) => new(DN(r, "TemperatureC"), IN(r, "Pulse"), IN(r, "Systolic"), IN(r, "Diastolic"), DN(r, "WeightKg"), IN(r, "Spo2"));
    private static TriageAssessment MapTriage(DbDataReader r) => new(G(r, "Id"), G(r, "RegistrationId"), S(r, "Category"), S(r, "Complaint"), MapVitals(r), G(r, "AssessedBy"), T(r, "AssessedAtUtc"));
    private static OtBooking MapOtBooking(DbDataReader r) => new(G(r, "Id"), S(r, "Number"), G(r, "PatientId"), GN(r, "AdmissionId"), S(r, "ProcedureName"), S(r, "Laterality"), S(r, "Site"), G(r, "SurgeonId"), S(r, "Anaesthesia"), S(r, "Priority"), S(r, "Status"),
        S(r, "Theatre"), TN(r, "ScheduledStartUtc"), TN(r, "ScheduledEndUtc"), T(r, "RequestedAtUtc"), G(r, "RequestedBy"), TN(r, "TimeInUtc"), TN(r, "TimeOutUtc"), S(r, "OperationNote"), L(r, "Version"));
    private static BloodUnit MapBloodUnit(DbDataReader r) => new(G(r, "Id"), S(r, "UnitNumber"), S(r, "BloodGroup"), S(r, "Component"), Date(r, "ExpiryDate"), S(r, "Status"), S(r, "DonorName"), T(r, "CollectedAtUtc"), L(r, "Version"));
    private static BloodIssue MapBloodIssue(DbDataReader r) => new(G(r, "Id"), S(r, "Number"), G(r, "UnitId"), G(r, "PatientId"), GN(r, "AdmissionId"), S(r, "Status"), S(r, "Reaction"), S(r, "ReturnAssessment"), G(r, "IssuedBy"), T(r, "IssuedAtUtc"), TN(r, "TransfusedAtUtc"), S(r, "Notes"), L(r, "Version"));
    public Task<RadiologyOrder?> FindRadiologyOrderAsync(Guid id, CancellationToken ct) => Query($"SELECT TOP(1) {RadiologyOrderColumns} FROM ris.Orders WHERE HospitalId=@h AND Id=@id", MapRadiologyOrder, H, ("id", id)).ContinueWith(t => t.Result.FirstOrDefault(), ct);
    public Task InsertRadiologyOrderAsync(RadiologyOrder o, CancellationToken ct) => Execute($"INSERT INTO ris.Orders({RadiologyOrderColumns}) VALUES(@id,@number,@patient,@encounter,@admission,@procedure,@modality,@bodyPart,@laterality,@priority,@status,@accession,@note,@by,@orderedAt,@scheduledAt,@performedAt,@uid,1)",
        ("id", o.Id), ("number", o.Number), ("patient", o.PatientId), ("encounter", o.EncounterId), ("admission", o.AdmissionId), ("procedure", o.Procedure), ("modality", o.Modality), ("bodyPart", o.BodyPart), ("laterality", o.Laterality), ("priority", o.Priority), ("status", o.Status), ("accession", o.Accession), ("note", o.ClinicalNote), ("by", o.OrderedBy), ("orderedAt", o.OrderedAt.UtcDateTime), ("scheduledAt", o.ScheduledAt?.UtcDateTime), ("performedAt", o.PerformedAt?.UtcDateTime), ("uid", o.StudyUid), H);
    public async Task UpdateRadiologyOrderAsync(RadiologyOrder o, CancellationToken ct)
    {
        if (await Execute("UPDATE ris.Orders SET Status=@status,Accession=@accession,ScheduledAtUtc=@scheduledAt,PerformedAtUtc=@performedAt,StudyUid=@uid,Version=@new WHERE Id=@id AND HospitalId=@h AND Version=@old AND Status NOT IN ('Authorized','Cancelled')",
            ("status", o.Status), ("accession", o.Accession), ("scheduledAt", o.ScheduledAt?.UtcDateTime), ("performedAt", o.PerformedAt?.UtcDateTime), ("uid", o.StudyUid), ("new", o.Version), ("id", o.Id), H, ("old", o.Version - 1)) != 1) throw Conflict();
    }
    public Task<RadiologyReport?> FindRadiologyReportByOrderAsync(Guid orderId, CancellationToken ct) => Query($"SELECT TOP(1) {RadiologyReportColumns} FROM ris.Reports WHERE HospitalId=@h AND OrderId=@id", MapRadiologyReport, H, ("id", orderId)).ContinueWith(t => t.Result.FirstOrDefault(), ct);
    public Task InsertRadiologyReportAsync(RadiologyReport r, CancellationToken ct) => Execute($"INSERT INTO ris.Reports({RadiologyReportColumns}) VALUES(@id,@order,1,@findings,@impression,@critical,@status,@by,@at,@aby,@aat,@hash)",
        ("id", r.Id), ("order", r.OrderId), ("findings", r.Findings), ("impression", r.Impression), ("critical", r.Critical), ("status", r.Status), ("by", r.ReportedBy), ("at", r.ReportedAt.UtcDateTime), ("aby", r.AuthorizedBy), ("aat", r.AuthorizedAt?.UtcDateTime), ("hash", r.ContentHash), H);
    public async Task UpdateRadiologyReportAsync(RadiologyReport r, CancellationToken ct)
    {
        if (await Execute("UPDATE ris.Reports SET Status=@status,AuthorizedBy=@aby,AuthorizedAtUtc=@aat,ContentHash=@hash,Version=@new WHERE Id=@id AND HospitalId=@h AND Status<>'Authorized'",
            ("status", r.Status), ("aby", r.AuthorizedBy), ("aat", r.AuthorizedAt?.UtcDateTime), ("hash", r.ContentHash), ("new", r.Version), ("id", r.Id), H) != 1) throw Conflict();
    }
    public Task<EmergencyRegistration?> FindEmergencyRegistrationAsync(Guid id, CancellationToken ct) => Query("SELECT TOP(1) Id,Number,PatientId,PatientName,Sex,DateOfBirth,ArrivalMode,Status,ArrivedAtUtc,CreatedBy,Version,ReferringFacility,BroughtBy,MedicoLegalCase FROM emergency.Registrations WHERE HospitalId=@h AND Id=@id", MapEmergencyRegistration, H, ("id", id)).ContinueWith(t => t.Result.FirstOrDefault(), ct);
    public Task InsertEmergencyRegistrationAsync(EmergencyRegistration r, CancellationToken ct) => Execute("INSERT INTO emergency.Registrations(Id,HospitalId,BranchId,Number,PatientId,PatientName,Sex,DateOfBirth,ArrivalMode,Status,ArrivedAtUtc,CreatedBy,Version,ReferringFacility,BroughtBy,MedicoLegalCase) VALUES(@id,@h,@b,@number,@patient,@name,@sex,@dob,@mode,'Open',@at,@by,1,@facility,@brought,@mlc)",
        ("id", r.Id), ("number", r.Number), ("patient", r.PatientId), ("name", r.PatientName), ("sex", r.Sex), ("dob", r.DateOfBirth), ("mode", r.ArrivalMode), ("at", r.ArrivedAt.UtcDateTime), ("by", r.CreatedBy), ("facility", r.ReferringFacility), ("brought", r.BroughtBy), ("mlc", r.MedicoLegalCase), H, Branch);
    public async Task UpdateEmergencyRegistrationAsync(EmergencyRegistration r, CancellationToken ct)
    {
        if (await Execute("UPDATE emergency.Registrations SET Status=@status,Version=@new WHERE Id=@id AND HospitalId=@h AND Version=@old AND Status='Open'", ("status", r.Status), ("new", r.Version), ("id", r.Id), H, ("old", r.Version - 1)) != 1) throw Conflict();
    }
    public Task InsertTriageAssessmentAsync(TriageAssessment t, CancellationToken ct) => Execute("INSERT INTO emergency.TriageAssessments(Id,HospitalId,RegistrationId,Category,Complaint,TemperatureC,Pulse,Systolic,Diastolic,WeightKg,Spo2,AssessedBy,AssessedAtUtc) VALUES(@id,@h,@reg,@category,@complaint,@temp,@pulse,@systolic,@diastolic,@weight,@spo2,@by,@at)",
        ("id", t.Id), ("reg", t.RegistrationId), ("category", t.Category), ("complaint", t.Complaint), ("temp", t.Vitals.TemperatureC), ("pulse", t.Vitals.Pulse), ("systolic", t.Vitals.Systolic), ("diastolic", t.Vitals.Diastolic), ("weight", t.Vitals.WeightKg), ("spo2", t.Vitals.Spo2), ("by", t.AssessedBy), ("at", t.AssessedAt.UtcDateTime), H);
    public Task InsertEmergencyObservationAsync(EmergencyObservation o, CancellationToken ct) => Execute("INSERT INTO emergency.Observations(Id,HospitalId,RegistrationId,Note,TemperatureC,Pulse,Systolic,Diastolic,WeightKg,Spo2,RecordedBy,RecordedAtUtc) VALUES(@id,@h,@reg,@note,@temp,@pulse,@systolic,@diastolic,@weight,@spo2,@by,@at)",
        ("id", o.Id), ("reg", o.RegistrationId), ("note", o.Note), ("temp", o.Vitals.TemperatureC), ("pulse", o.Vitals.Pulse), ("systolic", o.Vitals.Systolic), ("diastolic", o.Vitals.Diastolic), ("weight", o.Vitals.WeightKg), ("spo2", o.Vitals.Spo2), ("by", o.RecordedBy), ("at", o.RecordedAt.UtcDateTime), H);
    public Task InsertEmergencyDispositionAsync(EmergencyDisposition d, CancellationToken ct) => Execute("INSERT INTO emergency.Dispositions(Id,HospitalId,RegistrationId,Kind,Summary,AdmissionId,ReceivingFacility,DecidedBy,DecidedAtUtc) VALUES(@id,@h,@reg,@kind,@summary,@admission,@facility,@by,@at)",
        ("id", d.Id), ("reg", d.RegistrationId), ("kind", d.Kind), ("summary", d.Summary), ("admission", d.AdmissionId), ("facility", d.ReceivingFacility), ("by", d.DecidedBy), ("at", d.DecidedAt.UtcDateTime), H);
    public Task<OtBooking?> FindOtBookingAsync(Guid id, CancellationToken ct) => Query("SELECT TOP(1) Id,Number,PatientId,AdmissionId,ProcedureName,Laterality,Site,SurgeonId,Anaesthesia,Priority,Status,Theatre,ScheduledStartUtc,ScheduledEndUtc,RequestedAtUtc,RequestedBy,TimeInUtc,TimeOutUtc,OperationNote,Version FROM ot.Bookings WHERE HospitalId=@h AND Id=@id", MapOtBooking, H, ("id", id)).ContinueWith(t => t.Result.FirstOrDefault(), ct);
    public Task InsertOtBookingAsync(OtBooking b, CancellationToken ct) => Execute("INSERT INTO ot.Bookings(Id,HospitalId,BranchId,Number,PatientId,AdmissionId,ProcedureName,Laterality,Site,SurgeonId,Anaesthesia,Priority,Status,Theatre,ScheduledStartUtc,ScheduledEndUtc,RequestedAtUtc,RequestedBy,TimeInUtc,TimeOutUtc,OperationNote,Version) VALUES(@id,@h,@b,@number,@patient,@admission,@procedure,@laterality,@site,@surgeon,@anaesthesia,@priority,'Requested','',NULL,NULL,@at,@by,NULL,NULL,'',1)",
        ("id", b.Id), ("number", b.Number), ("patient", b.PatientId), ("admission", b.AdmissionId), ("procedure", b.Procedure), ("laterality", b.Laterality), ("site", b.Site), ("surgeon", b.SurgeonId), ("anaesthesia", b.Anaesthesia), ("priority", b.Priority), ("at", b.RequestedAt.UtcDateTime), ("by", b.RequestedBy), H, Branch);
    public async Task UpdateOtBookingAsync(OtBooking b, CancellationToken ct)
    {
        if (await Execute("UPDATE ot.Bookings SET Status=@status,Theatre=@theatre,ScheduledStartUtc=@start,ScheduledEndUtc=@end,TimeInUtc=@timeIn,TimeOutUtc=@timeOut,OperationNote=@note,Version=@new WHERE Id=@id AND HospitalId=@h AND Version=@old AND Status NOT IN ('Completed','Cancelled')",
            ("status", b.Status), ("theatre", b.Theatre), ("start", b.ScheduledStart?.UtcDateTime), ("end", b.ScheduledEnd?.UtcDateTime), ("timeIn", b.TimeIn?.UtcDateTime), ("timeOut", b.TimeOut?.UtcDateTime), ("note", b.OperationNote), ("new", b.Version), ("id", b.Id), H, ("old", b.Version - 1)) != 1) throw Conflict();
    }
    public Task<OtChecklist?> FindOtChecklistAsync(Guid bookingId, CancellationToken ct) => Query("SELECT TOP(1) Id,BookingId,Consent,AnaesthesiaAssessment,FastingConfirmed,SiteMarked,SafetyChecklist,Notes,RecordedBy,RecordedAtUtc FROM ot.Checklists WHERE HospitalId=@h AND BookingId=@id",
        r => new OtChecklist(G(r, "Id"), G(r, "BookingId"), B(r, "Consent"), B(r, "AnaesthesiaAssessment"), B(r, "FastingConfirmed"), B(r, "SiteMarked"), B(r, "SafetyChecklist"), S(r, "Notes"), G(r, "RecordedBy"), T(r, "RecordedAtUtc")), H, ("id", bookingId)).ContinueWith(t => t.Result.FirstOrDefault(), ct);
    public Task InsertOtChecklistAsync(OtChecklist c, CancellationToken ct) => Execute("INSERT INTO ot.Checklists(Id,HospitalId,BookingId,Consent,AnaesthesiaAssessment,FastingConfirmed,SiteMarked,SafetyChecklist,Notes,RecordedBy,RecordedAtUtc) VALUES(@id,@h,@booking,1,1,1,1,1,@notes,@by,@at)",
        ("id", c.Id), ("booking", c.BookingId), ("notes", c.Notes), ("by", c.RecordedBy), ("at", c.RecordedAt.UtcDateTime), H);
    public Task<bool> HasOtConflictAsync(string theatre, DateTimeOffset start, DateTimeOffset end, Guid? excludeId, CancellationToken ct) =>
        Query("SELECT COUNT(1) FROM ot.Bookings WHERE HospitalId=@h AND Theatre=@theatre AND Status IN ('Scheduled','In Theatre','Recovery') AND ScheduledStartUtc<@end AND ScheduledEndUtc>@start AND (@exclude IS NULL OR Id<>@exclude)",
            r => Convert.ToInt32(r[0]), H, ("theatre", theatre), ("start", start.UtcDateTime), ("end", end.UtcDateTime), ("exclude", excludeId)).ContinueWith(t => t.Result[0] > 0, ct);
    public Task<BloodUnit?> FindBloodUnitAsync(Guid id, CancellationToken ct) => Query("SELECT TOP(1) Id,UnitNumber,BloodGroup,Component,ExpiryDate,Status,DonorName,CollectedAtUtc,Version FROM blood.Units WHERE HospitalId=@h AND Id=@id", MapBloodUnit, H, ("id", id)).ContinueWith(t => t.Result.FirstOrDefault(), ct);
    public Task<BloodUnit?> FindBloodUnitByNumberAsync(string unitNumber, CancellationToken ct) => Query("SELECT TOP(1) Id,UnitNumber,BloodGroup,Component,ExpiryDate,Status,DonorName,CollectedAtUtc,Version FROM blood.Units WHERE HospitalId=@h AND UnitNumber=@number", MapBloodUnit, H, ("number", unitNumber)).ContinueWith(t => t.Result.FirstOrDefault(), ct);
    public Task InsertBloodUnitAsync(BloodUnit u, CancellationToken ct) => Execute("INSERT INTO blood.Units(Id,HospitalId,BranchId,UnitNumber,BloodGroup,Component,ExpiryDate,Status,DonorName,CollectedAtUtc,Version) VALUES(@id,@h,@b,@number,@group,@component,@expiry,'Quarantined',@donor,@at,1)",
        ("id", u.Id), ("number", u.UnitNumber), ("group", u.BloodGroup), ("component", u.Component), ("expiry", u.ExpiryDate), ("donor", u.DonorName), ("at", u.CollectedAt.UtcDateTime), H, Branch);
    public async Task UpdateBloodUnitAsync(BloodUnit u, CancellationToken ct)
    {
        if (await Execute("UPDATE blood.Units SET Status=@status,Version=@new WHERE Id=@id AND HospitalId=@h AND Version=@old AND Status NOT IN ('Transfused','Discarded')", ("status", u.Status), ("new", u.Version), ("id", u.Id), H, ("old", u.Version - 1)) != 1) throw Conflict();
    }
    public Task<BloodScreening?> FindScreeningAsync(Guid unitId, CancellationToken ct) => Query("SELECT TOP(1) Id,UnitId,Hbsag,Hiv,Hcv,Vdrl,Notes,TestedBy,TestedAtUtc FROM blood.ScreeningTests WHERE HospitalId=@h AND UnitId=@id",
        r => new BloodScreening(G(r, "Id"), G(r, "UnitId"), B(r, "Hbsag"), B(r, "Hiv"), B(r, "Hcv"), B(r, "Vdrl"), S(r, "Notes"), G(r, "TestedBy"), T(r, "TestedAtUtc")), H, ("id", unitId)).ContinueWith(t => t.Result.FirstOrDefault(), ct);
    public Task InsertScreeningAsync(BloodScreening s, CancellationToken ct) => Execute("INSERT INTO blood.ScreeningTests(Id,HospitalId,UnitId,Hbsag,Hiv,Hcv,Vdrl,Notes,TestedBy,TestedAtUtc) VALUES(@id,@h,@unit,@hbsag,@hiv,@hcv,@vdrl,@notes,@by,@at)",
        ("id", s.Id), ("unit", s.UnitId), ("hbsag", s.Hbsag), ("hiv", s.Hiv), ("hcv", s.Hcv), ("vdrl", s.Vdrl), ("notes", s.Notes), ("by", s.TestedBy), ("at", s.TestedAt.UtcDateTime), H);
    public Task<Crossmatch?> FindActiveCrossmatchAsync(Guid unitId, Guid patientId, CancellationToken ct) => Query("SELECT TOP(1) Id,Number,UnitId,PatientId,Compatibility,Status,TestedBy,TestedAtUtc FROM blood.Crossmatches WHERE HospitalId=@h AND UnitId=@unit AND PatientId=@patient AND Status='Matched'",
        r => new Crossmatch(G(r, "Id"), S(r, "Number"), G(r, "UnitId"), G(r, "PatientId"), S(r, "Compatibility"), S(r, "Status"), G(r, "TestedBy"), T(r, "TestedAtUtc")), H, ("unit", unitId), ("patient", patientId)).ContinueWith(t => t.Result.FirstOrDefault(), ct);
    public Task InsertCrossmatchAsync(Crossmatch x, CancellationToken ct) => Execute("INSERT INTO blood.Crossmatches(Id,HospitalId,Number,UnitId,PatientId,Compatibility,Status,TestedBy,TestedAtUtc) VALUES(@id,@h,@number,@unit,@patient,@compatibility,'Matched',@by,@at)",
        ("id", x.Id), ("number", x.Number), ("unit", x.UnitId), ("patient", x.PatientId), ("compatibility", x.Compatibility), ("by", x.TestedBy), ("at", x.TestedAt.UtcDateTime), H);
    public Task<BloodIssue?> FindBloodIssueAsync(Guid id, CancellationToken ct) => Query("SELECT TOP(1) Id,Number,UnitId,PatientId,AdmissionId,Status,Reaction,ReturnAssessment,IssuedBy,IssuedAtUtc,TransfusedAtUtc,Notes,Version FROM blood.Issues WHERE HospitalId=@h AND Id=@id", MapBloodIssue, H, ("id", id)).ContinueWith(t => t.Result.FirstOrDefault(), ct);
    public Task<BloodIssue?> FindOpenBloodIssueAsync(Guid unitId, CancellationToken ct) => Query("SELECT TOP(1) Id,Number,UnitId,PatientId,AdmissionId,Status,Reaction,ReturnAssessment,IssuedBy,IssuedAtUtc,TransfusedAtUtc,Notes,Version FROM blood.Issues WHERE HospitalId=@h AND UnitId=@unit AND Status='Issued'", MapBloodIssue, H, ("unit", unitId)).ContinueWith(t => t.Result.FirstOrDefault(), ct);
    public Task InsertBloodIssueAsync(BloodIssue i, CancellationToken ct) => Execute("INSERT INTO blood.Issues(Id,HospitalId,Number,UnitId,PatientId,AdmissionId,Status,Reaction,ReturnAssessment,IssuedBy,IssuedAtUtc,TransfusedAtUtc,Notes,Version) VALUES(@id,@h,@number,@unit,@patient,@admission,'Issued','','',@by,@at,NULL,@notes,1)",
        ("id", i.Id), ("number", i.Number), ("unit", i.UnitId), ("patient", i.PatientId), ("admission", i.AdmissionId), ("by", i.IssuedBy), ("at", i.IssuedAt.UtcDateTime), ("notes", i.Notes), H);
    public async Task UpdateBloodIssueAsync(BloodIssue i, CancellationToken ct)
    {
        if (await Execute("UPDATE blood.Issues SET Status=@status,Reaction=@reaction,ReturnAssessment=@assessment,TransfusedAtUtc=@transfusedAt,Notes=@notes,Version=@new WHERE Id=@id AND HospitalId=@h AND Version=@old AND Status='Issued'",
            ("status", i.Status), ("reaction", i.Reaction), ("assessment", i.ReturnAssessment), ("transfusedAt", i.TransfusedAt?.UtcDateTime), ("notes", i.Notes), ("new", i.Version), ("id", i.Id), H, ("old", i.Version - 1)) != 1) throw Conflict();
    }
}
